  .ob{border:1px solid #cdd5df;border-radius:6px;padding:8px;min-height:44px;white-space:pre-wrap}.ft{margin-top:14px;font-size:9px;color:#6b7686;border-top:1px solid #cdd5df;padding-top:6px}
  </style></head><body>
